let img;
let time = 0;

function preload() {
  img = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/text.png');
}

function setup() {
  createCanvas(600, 600, WEBGL);
  noStroke();

  textureMode(NORMAL);
  textureWrap(REPEAT);
}

function draw() {
  background('#CDDC39');
  orbitControl();

  for(let i = 0; i < PI*2; i+= (Math.max(0.001, Math.abs(PI*2/6)) || 1)){
    push();
      translate(0,0, -PI*2/6)
      rotate(i)
      drawLeaf(time);
    pop(); 
  }
  time += 0.05;
}

function drawLeaf(){

  let step = 150;
  let size = 50;
  let len = PI;
  let len2 = 85;

  texture(img);

  beginShape(TRIANGLE_STRIP);
  vertex(0, 0, 0, 0,0 );

  for(let i = 0; i <= len; i+= (Math.max(0.001, Math.abs(len/step)) || 1)){
    vertex(i * len2, sin(i) * size, (sin((i*1.5 + (time))))*75, i/len + cos(time/2), 1)
    vertex(i * len2, -sin(i) * size,  (sin((i*1.5 +(time))))*75, i/len  + sin(time/2), 0)
  }
  endShape(CLOSE)
}
